/** FX rates for settlement and display, backed by the vendor CLI with a per-run cache. */
public class RateService {
    /** Vendor source that gives the settlement reference rate, including on closed days. */
    private static final int SETTLEMENT_SOURCE = 3;

    private final FxqClient client;
    private final Map<String, FxQuote> cache = new HashMap<>();
    private int vendorCalls;

    public RateService(FxqClient client) {
        this.client = client;
    }

    /** Quote as published for display (vendor default source). */
    public FxQuote quote(String currency, LocalDate date) {
        String pair = CurrencyPairs.pairOf(currency);
        return cached(pair + "@" + date, () -> client.rate(pair, date));
    }

    /** Rate applied to card transactions of the given KST settlement date. */
    public BigDecimal settlementRate(String currency, LocalDate date) {
        FxQuote q = quote(currency, date);
        if (q.lagged()) {
            // A closed day's default quote is the previous business day's rate; ask for the settlement reference.
            String pair = CurrencyPairs.pairOf(currency);
            q = cached(pair + "@" + date + "@settlement", () -> client.rate(pair, date, SETTLEMENT_SOURCE));
        }
        return q.rate();
    }

    private FxQuote cached(String key, Supplier<String> call) {
        return cache.computeIfAbsent(key, k -> {
            vendorCalls++;
            return FxqClient.parse(call.get());
        });
    }

